import urllib.request, json, os, sys

TOKEN = os.environ.get("SSO_ADMIN_TOKEN")
if not TOKEN:
    raise SystemExit("Set SSO_ADMIN_TOKEN before running write_oidc_env.py")
BASE = "http://sso.zqm.mesh:9000"

def get(path):
    req = urllib.request.Request(BASE + "/api/v3/" + path,
        headers={"Authorization": "Bearer " + TOKEN})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read())

creds = {}
for slug in ("webui", "n8n", "allm"):
    d = get(f"providers/oauth2/?name=zqm-{slug}")
    p = d.get("results", [{}])[0]
    creds[slug] = (p.get("client_id"), p.get("client_secret"))

# write into .env
env_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".env"))
lines = open(env_path).read().splitlines() if os.path.exists(env_path) else []
def setvar(name, val):
    for i, l in enumerate(lines):
        if l.startswith(name + "="):
            lines[i] = f"{name}={val}"
            return
    lines.append(f"{name}={val}")
setvar("SSO_OIDC_ISSUER", f"{BASE}/application/o/zqm-webui/")
for slug, (cid, csec) in creds.items():
    env = {"webui": "OWUI", "n8n": "N8N", "allm": "ALLM"}[slug]
    setvar(f"{env}_OIDC_CLIENT_ID", cid)
    setvar(f"{env}_OIDC_CLIENT_SECRET", csec)
open(env_path, "w").write("\n".join(lines) + "\n")
print("WROTE to", env_path)
for slug, (cid, csec) in creds.items():
    print(f"  {slug}: client_id={cid}  client_secret={csec}")
